async function r(i,t,n){const s=[],e=i.toLowerCase();return e.includes("umbrella")||e.includes("rain")?s.push("High correlation with precipitation patterns expected."):e.includes("winter")||e.includes("heater")||e.includes("jacket")?s.push("Demand highly sensitive to temperature drops in winter months."):e.includes("summer")||e.includes("ac")||e.includes("cooler")?s.push("Demand surges during peak summer temperatures."):s.push("Stable baseline demand expected based on category trends."),["electronics","mobile","fashion"].includes(t.toLowerCase())&&s.push("Strong social media momentum identified for this category."),s}export{r as generateInsights};
